import { chartChrome, chartSeries } from '06_shared/constants/colors';
import { chartFont } from '06_shared/constants/tokens';
import { correlationAxisBound, formatShiftMinutes } from './analysisSummary';
// Нижня межа смуги шуму — без підпису: у легенді й підказці лише верхня.
export const NOISE_LOWER = '';
// Крива зсувів: по X — зсув у хвилинах (+ спершу рух BTC, потім угоди), по Y —
// кореляція Пірсона зміни ціни з кількістю відкритих угод. Пунктир — смуга
// шуму: усе всередині неї випадкові ряди дають самі собою (p ≥ 0.05).
export const prepareAnalysisChartDataAndOptions = (result, theme, labels) => {
    const { axis, grid, baseline } = chartChrome(theme);
    const points = result.change_lag_list;
    const noise = points.map((p) => p.noise_corr);
    const bound = correlationAxisBound([
        ...points.map((p) => p.corr_buy),
        ...points.map((p) => p.corr_sell),
        ...noise,
    ]);
    const line = {
        pointRadius: 0,
        pointHoverRadius: 4,
        tension: 0,
        borderWidth: 2,
        spanGaps: false,
    };
    const noiseLine = {
        borderColor: axis,
        borderDash: [4, 4],
        borderWidth: 1,
        pointRadius: 0,
        pointHoverRadius: 0,
        fill: false,
    };
    const data = {
        labels: points.map((p) => formatShiftMinutes(p.lag * result.sample_minutes)),
        datasets: [
            {
                label: labels.longs,
                data: points.map((p) => p.corr_buy),
                ...chartSeries(theme, 'long'),
                ...line,
            },
            {
                label: labels.shorts,
                data: points.map((p) => p.corr_sell),
                ...chartSeries(theme, 'short'),
                ...line,
            },
            {
                label: labels.noise,
                data: noise,
                ...noiseLine,
            },
            {
                label: NOISE_LOWER,
                data: noise.map((value) => (value === null ? null : -value)),
                ...noiseLine,
            },
        ],
    };
    const options = {
        responsive: true,
        maintainAspectRatio: false,
        interaction: {
            mode: 'index',
            intersect: false,
        },
        animation: {
            duration: 250,
            easing: 'easeInOutCubic',
        },
        plugins: {
            legend: {
                display: true,
                position: 'top',
                labels: {
                    color: axis,
                    font: chartFont('bodyS'),
                    boxWidth: 16,
                    filter: (item) => item.text !== NOISE_LOWER,
                },
            },
            tooltip: {
                enabled: true,
                titleFont: chartFont('body'),
                bodyFont: chartFont('bodyS'),
                filter: (item) => item.dataset.label !== NOISE_LOWER,
                callbacks: {
                    title: (items) => (items[0] ? `${items[0].label} ${labels.minutes}` : ''),
                    label: (item) => {
                        const value = item.parsed.y;
                        const shown = value === null ? '—' : value.toFixed(3);
                        return item.dataset.label === labels.noise
                            ? `${item.dataset.label}: ±${shown}`
                            : `${item.dataset.label}: r = ${shown}`;
                    },
                },
            },
            annotation: {
                annotations: {
                    zeroShift: {
                        type: 'line',
                        scaleID: 'x',
                        value: '0',
                        borderColor: baseline,
                        borderWidth: 1,
                    },
                    zeroCorr: {
                        type: 'line',
                        scaleID: 'y',
                        value: 0,
                        borderColor: baseline,
                        borderWidth: 1,
                    },
                },
            },
        },
        scales: {
            x: {
                title: {
                    display: true,
                    text: labels.axisX,
                    color: axis,
                    font: chartFont('caption'),
                },
                grid: {
                    display: true,
                    drawOnChartArea: false,
                    drawTicks: false,
                },
                ticks: {
                    color: axis,
                    maxTicksLimit: 13,
                    font: chartFont('bodyS'),
                },
                border: {
                    color: axis,
                },
            },
            y: {
                type: 'linear',
                position: 'left',
                min: -bound,
                max: bound,
                title: {
                    display: true,
                    text: labels.axisY,
                    color: axis,
                    font: chartFont('caption'),
                },
                grid: {
                    drawOnChartArea: true,
                    color: grid,
                },
                ticks: {
                    color: axis,
                    font: chartFont('bodyS'),
                },
                border: {
                    color: axis,
                },
            },
        },
    };
    return { data, options };
};
