// Межі сили зв'язку за |r|: r = 0.1 пояснює лише 1% розкиду угод.
const WEAK_BELOW = 0.1;
const MODERATE_BELOW = 0.3;
export const formatShiftMinutes = (minutes) => (minutes > 0 ? `+${minutes}` : String(minutes));
export const formatPValue = (p) => (p < 0.001 ? '< 0.001' : p.toFixed(3));
const strength = (t, r) => {
    const abs = Math.abs(r);
    if (abs < WEAK_BELOW)
        return t('weak link');
    if (abs < MODERATE_BELOW)
        return t('moderate link');
    return t('strong link');
};
const movement = (t, best) => {
    const rises = best.corr > 0;
    if (best.lag > 0) {
        return rises ? t('Opens more after BTC rises') : t('Opens more after BTC falls');
    }
    if (best.lag < 0) {
        return rises ? t('Opens more before BTC rises') : t('Opens more before BTC falls');
    }
    return rises ? t('Opens more while BTC rises') : t('Opens more while BTC falls');
};
// Підсумок однієї сторони: чи пов'язане відкриття угод із рухом BTC. Значущий
// лише найкращий зсув, що пройшов поправку на кількість перевірених зсувів.
// Рядків подробиць завжди чотири (без виміру — з прочерками): картка й її
// заглушка однакової висоти за будь-якої відповіді.
export const summarizeSide = (t, best, sampleMinutes, trades) => {
    const tradesLine = `${t('Trades opened')}: ${trades}`;
    if (!best) {
        return {
            verdict: t('Not measurable — too few trades or samples'),
            tone: 'neutral',
            details: [`${t('Best shift')}: —`, 'r: —', `${t('p adjusted')}: —`, tradesLine],
        };
    }
    const r = `r = ${best.corr.toFixed(3)}`;
    const shift = `${t('Best shift')}: ${formatShiftMinutes(best.lag * sampleMinutes)} ${t('min')}`;
    const p = `${t('p adjusted')}: ${formatPValue(best.p_value_adjusted)}`;
    if (!best.significant) {
        return {
            verdict: t('Noise — no link to BTC moves'),
            tone: 'neutral',
            details: [shift, r, p, tradesLine],
        };
    }
    return {
        verdict: movement(t, best),
        tone: 'info',
        details: [shift, `${r} — ${strength(t, best.corr)}`, p, tradesLine],
    };
};
// Симетрична межа осі r: найбільше |r| чи смуга шуму з запасом, не менше 0.1
// і не більше 1 — щоб слабка кореляція не губилася біля нуля шкали ±1.
export const correlationAxisBound = (values) => {
    const top = values.reduce((max, value) => (value === null ? max : Math.max(max, Math.abs(value))), 0);
    const bound = Math.ceil(top * 1.2 * 20) / 20;
    return Math.min(1, Math.max(0.1, bound));
};
